#define _POSIX_C_SOURCE 200809L
#include "cvc_object.h"
#include "cvc_sha256.h"
#include <string.h>
#include <stdio.h>
#include <stdlib.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>

const char*cvc_obj_type_name(CvcObjType t){switch(t){case CVC_OBJ_BLOB:return"blob";case CVC_OBJ_SYMLINK:return"symlink";case CVC_OBJ_TREE:return"tree";case CVC_OBJ_COMMIT:return"commit";default:return NULL;}}
void cvc_object_envelope(CvcObjType t,const void*p,size_t n,CvcBuf*out){cvc_buf_init(out);const char*s=cvc_obj_type_name(t);if(!s)return;cvc_buf_append(out,s,strlen(s));cvc_buf_putc(out,' ');char z[32];int k=snprintf(z,sizeof(z),"%zu",n);cvc_buf_append(out,z,(size_t)k);cvc_buf_putc(out,0);cvc_buf_append(out,p,n);}
void cvc_object_oid(CvcObjType t,const void*p,size_t n,uint8_t oid[32]){CvcBuf b;cvc_object_envelope(t,p,n,&b);cvc_sha256(b.data,b.len,oid);cvc_buf_free(&b);}
char*cvc_object_path(const char*cvc,const uint8_t oid[32]){char h[65];cvc_hex_encode(oid,32,h);char pre[3]={h[0],h[1],0};char*d=cvc_path_join(cvc,"objects");char*d2=cvc_path_join(d,pre);free(d);char*p=cvc_path_join(d2,h+2);free(d2);return p;}
static int parse_envelope(const CvcBuf*whole,CvcObjType*t,CvcBuf*payload){size_t i=0;while(i<whole->len&&whole->data[i]!=' ')i++;if(i==0||i>=whole->len)return -1;CvcObjType typ=0;if(i==4&&!memcmp(whole->data,"blob",4))typ=CVC_OBJ_BLOB;else if(i==7&&!memcmp(whole->data,"symlink",7))typ=CVC_OBJ_SYMLINK;else if(i==4&&!memcmp(whole->data,"tree",4))typ=CVC_OBJ_TREE;else if(i==6&&!memcmp(whole->data,"commit",6))typ=CVC_OBJ_COMMIT;else return -1;size_t j=i+1;if(j>=whole->len)return -1;size_t ds=j;while(j<whole->len&&whole->data[j]!=0){if(whole->data[j]<'0'||whole->data[j]>'9')return -1;j++;}if(j==whole->len||j==ds)return -1;if(j-ds>1&&whole->data[ds]=='0')return -1;uint64_t n=0;for(size_t k=ds;k<j;k++){unsigned d=(unsigned)(whole->data[k]-'0');if(n>(UINT64_MAX-d)/10)return -1;n=n*10+d;}size_t off=j+1;if(n>SIZE_MAX||off>whole->len||(size_t)n!=whole->len-off)return -1;*t=typ;cvc_buf_init(payload);cvc_buf_append(payload,whole->data+off,(size_t)n);return 0;}
int cvc_object_read(const char*cvc,const uint8_t oid[32],CvcObjType*t,CvcBuf*payload){char*p=cvc_object_path(cvc,oid);char*dir=cvc_path_dirname(p);if(!cvc_is_real_dir(dir)){free(dir);free(p);return cvc_errorf("missing/unsafe object fanout");}free(dir);struct stat st;if(lstat(p,&st)<0||!S_ISREG(st.st_mode)){int e=errno;free(p);errno=e;return cvc_errorf("missing/unsafe object");}CvcBuf w;if(cvc_read_file_nofollow(p,&w)<0){int e=errno;free(p);return cvc_errorf("cannot read object: %s",strerror(e));}uint8_t got[32];cvc_sha256(w.data,w.len,got);if(memcmp(got,oid,32)){char h[65];cvc_hex_encode(oid,32,h);cvc_buf_free(&w);free(p);return cvc_errorf("object hash mismatch: %s",h);}if(parse_envelope(&w,t,payload)<0){cvc_buf_free(&w);free(p);return cvc_errorf("noncanonical object envelope");}cvc_buf_free(&w);free(p);return 0;}
int cvc_object_read_hex(const char*cvc,const char h[65],CvcObjType*t,CvcBuf*p){uint8_t id[32];if(!cvc_hex_decode_32(h,id))return cvc_errorf("invalid object id");return cvc_object_read(cvc,id,t,p);}
static int validate_payload(CvcObjType t,const unsigned char*p,size_t n){if(t==CVC_OBJ_BLOB){if(n>CVC_TEXT_MAX)return -1;size_t z=n<CVC_PROBE_MAX?n:CVC_PROBE_MAX;if(memchr(p,0,z))return -1;return 0;}if(t==CVC_OBJ_SYMLINK)return memchr(p,0,n)?-1:0;if(t==CVC_OBJ_TREE){CvcTree tr;int rc=cvc_tree_parse(p,n,&tr,1);if(!rc)cvc_tree_free(&tr);return rc;}if(t==CVC_OBJ_COMMIT){CvcCommit c;int rc=cvc_commit_parse(p,n,&c);if(!rc)cvc_commit_free(&c);return rc;}return -1;}
int cvc_object_store(const char*cvc,CvcObjType t,const void*p,size_t n,uint8_t oid[32]){if(validate_payload(t,p,n)<0)return cvc_errorf("refusing invalid object payload");CvcBuf w;cvc_object_envelope(t,p,n,&w);cvc_sha256(w.data,w.len,oid);char*final=cvc_object_path(cvc,oid);char*dir=cvc_path_dirname(final);if(!cvc_is_real_dir(dir)){if(mkdir(dir,0777)<0&&errno!=EEXIST){int e=errno;free(final);free(dir);cvc_buf_free(&w);return cvc_errorf("create object fanout: %s",strerror(e));}if(!cvc_is_real_dir(dir)){free(final);free(dir);cvc_buf_free(&w);return cvc_errorf("unsafe object fanout directory");}}
if(cvc_lstat_exists(final)){CvcObjType et;CvcBuf ep;if(cvc_object_read(cvc,oid,&et,&ep)<0){free(final);free(dir);cvc_buf_free(&w);return -1;}int ok=et==t&&ep.len==n&&!memcmp(ep.data,p,n);cvc_buf_free(&ep);free(final);free(dir);cvc_buf_free(&w);return ok?0:cvc_errorf("existing object content/type mismatch");}
size_t nd=strlen(dir);char*tmp=cvc_xmalloc(nd+32);snprintf(tmp,nd+32,"%s/.tmp-object-XXXXXX",dir);int fd=mkstemp(tmp);if(fd<0){int e=errno;free(final);free(dir);free(tmp);cvc_buf_free(&w);return cvc_errorf("create temporary object: %s",strerror(e));}int rc=0,e=0;if(cvc_write_all(fd,w.data,w.len)<0||fsync(fd)<0){rc=-1;e=errno;}if(close(fd)<0&&rc==0){rc=-1;e=errno;}if(rc==0){if(link(tmp,final)<0){if(errno==EEXIST){CvcObjType et;CvcBuf ep;if(cvc_object_read(cvc,oid,&et,&ep)<0)rc=-1;else{if(et!=t||ep.len!=n||memcmp(ep.data,p,n))rc=-1,e=EIO;cvc_buf_free(&ep);}}else rc=-1,e=errno;}}
unlink(tmp);if(rc==0){int dfd=open(dir,O_RDONLY|O_DIRECTORY|O_CLOEXEC|O_NOFOLLOW);if(dfd<0||fsync(dfd)<0){rc=-1;e=errno;}if(dfd>=0)close(dfd);}free(final);free(dir);free(tmp);cvc_buf_free(&w);if(rc<0){errno=e;return cvc_errorf("install object failed: %s",strerror(errno));}return 0;}
int cvc_tree_parse(const unsigned char*p,size_t n,CvcTree*out,int allow_empty){out->v=NULL;out->n=0;if(n<4)return -1;uint32_t cnt=cvc_get_u32be(p);size_t off=4;if(cnt==0){return (n==4&&allow_empty)?0:-1;}CvcTreeEntry*e=cvc_xcalloc(cnt,sizeof(*e));for(uint32_t i=0;i<cnt;i++){if(off+5>n)goto bad;uint8_t ty=p[off++];uint32_t nl=cvc_get_u32be(p+off);off+=4;if((ty<1||ty>3)||!nl||off+(size_t)nl+32>n)goto bad;if(!cvc_name_component_valid(p+off,nl))goto bad;e[i].type=ty;e[i].name=cvc_xstrndup((const char*)p+off,nl);e[i].name_len=nl;off+=nl;memcpy(e[i].oid,p+off,32);off+=32;if(i){size_t mn=e[i-1].name_len<nl?e[i-1].name_len:nl;int c=cvc_bytes_cmp(e[i-1].name,e[i].name,mn);if(c>0||(c==0&&e[i-1].name_len>=nl))goto bad;}}
if(off!=n)goto bad;
out->v=e;out->n=cnt;return 0;
bad:for(uint32_t i=0;i<cnt;i++)free(e[i].name);free(e);return -1;}
void cvc_tree_free(CvcTree*t){for(size_t i=0;i<t->n;i++)free(t->v[i].name);free(t->v);t->v=NULL;t->n=0;}
int cvc_commit_parse(const unsigned char*p,size_t n,CvcCommit*out){memset(out,0,sizeof(*out));if(n<32+1+8+8)return -1;size_t off=0;memcpy(out->root,p,32);off+=32;out->parent_count=p[off++];if(out->parent_count>2||off+(size_t)out->parent_count*32+16>n)return -1;for(unsigned i=0;i<out->parent_count;i++){memcpy(out->parents[i],p+off,32);off+=32;}if(out->parent_count==2&&!memcmp(out->parents[0],out->parents[1],32))return -1;out->timestamp=(int64_t)cvc_get_u64be(p+off);off+=8;uint64_t ml=cvc_get_u64be(p+off);off+=8;if(ml==0||ml>SIZE_MAX||off+(size_t)ml!=n)return -1;if(!cvc_utf8_valid(p+off,(size_t)ml))return -1;out->message=cvc_xmalloc((size_t)ml);memcpy(out->message,p+off,(size_t)ml);out->message_len=(size_t)ml;return 0;}
void cvc_commit_free(CvcCommit*c){free(c->message);memset(c,0,sizeof(*c));}
int cvc_commit_store(const char*cvc,const uint8_t root[32],uint8_t pc,const uint8_t *parents,int64_t ts,const unsigned char*msg,size_t ml,uint8_t oid[32]){if(pc>2||!ml||!cvc_utf8_valid(msg,ml)|| (pc==2&&!memcmp(parents,parents + 32,32)))return cvc_errorf("invalid commit fields");CvcBuf p;cvc_buf_init(&p);cvc_buf_append(&p,root,32);cvc_buf_putc(&p,pc);for(unsigned i=0;i<pc;i++)cvc_buf_append(&p,parents + (size_t)i * 32,32);cvc_put_u64be(&p,(uint64_t)ts);cvc_put_u64be(&p,(uint64_t)ml);cvc_buf_append(&p,msg,ml);int rc=cvc_object_store(cvc,CVC_OBJ_COMMIT,p.data,p.len,oid);cvc_buf_free(&p);return rc;}
